def copyRandomList(head):
    if not head:
        return None
    m = {}
    cur = head
    while cur:
        m[cur] = Node(cur.val)
        cur = cur.next
    cur = head
    while cur:
        m[cur].next = m.get(cur.next)
        m[cur].random = m.get(cur.random)
        cur = cur.next
    return m[head]

brute_force_solution:
def copyRandomList(head):
    nodes = []
    cur = head
    while cur:
        nodes.append(cur)
        cur = cur.next
    new = [Node(n.val) for n in nodes]
    for i, n in enumerate(nodes):
        if i + 1 < len(nodes):
            new[i].next = new[i + 1]
        if n.random is not None:
            j = 0
            while nodes[j] is not n.random:
                j += 1
            new[i].random = new[j]
    return new[0] if new else None

